# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">2. ÜNİTE: HZ. HATİCE\'NİN (R.A.) HAYATI, ŞAHSİYETİ VE TÂHİRE UNVANI (PH.9.2.1)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SOYU, AİLESİ VE TİCARİ İTİBARI</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• Tam Adı: Hatice bint Huveylid (r.a.)</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#1e3a8a">• Kabilesi: Kureyş\'in Esed boyu (Mekke, ~556)</text>\n  <text x="35" y="144" font-size="11" font-weight="bold" fill="#1e3a8a">• Mesleği: Mekke\'nin saygın ve dürüst taciri</text>\n  <text x="35" y="168" font-size="11" font-weight="bold" fill="#1e3a8a">• Özelliği: Yoksulları doyuran, yetimleri koruyan,</text>\n  <text x="45" y="186" font-size="10.5" fill="#1d4ed8">borçlulara destek olan cömert ve bilge hanım.</text>\n  <text x="35" y="214" font-size="11" font-weight="bold" fill="#b91c1c">• Müminlerin Annesi: Ümmü\'l-Mü\'minîn</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">CAHİLİYE DÖNEMİNDEKİ UNVANLARI</text>\n  <rect x="378" y="84" width="284" height="65" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="520" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">1. اَلطَّاهِرَةُ (TÂHİRE)</text>\n  <text x="520" y="126" text-anchor="middle" font-size="10.5" fill="#166534">Cahiliye kötülüklerinden uzak duran, iffetli,</text>\n  <text x="520" y="141" text-anchor="middle" font-size="10.5" fill="#166534">nezih, tertemiz ve yüksek ahlak sahibi.</text>\n  <rect x="378" y="160" width="284" height="65" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">2. سَيِّدَةُ نِسَاءِ قُرَيْشٍ (KUREYŞ HANIMLARININ EFENDİSİ)</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#166534">Asaleti, bilgeliği, vakarı ve hayırseverliğiyle</text>\n  <text x="520" y="217" text-anchor="middle" font-size="10.5" fill="#166534">Mekke toplumunda kazandığı saygın konum.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ŞAM TİCARET KERVANI, EVLİLİK SÜRECİ (595) VE ÖRNEK AİLE HAYATI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">TİCARİ ORTAKLIK VE EVLİLİK (M. 595)</text>\n  <text x="35" y="96" font-size="10.5" font-weight="bold" fill="#78350f">• Muhammedü\'l-Emîn ile Şam Kervanı ortaklığı</text>\n  <text x="35" y="120" font-size="10.5" font-weight="bold" fill="#78350f">• Yardımcısı Meysere\'nin Hz. Peygamber\'in dürüstlüğü,</text>\n  <text x="45" y="136" font-size="10.5" fill="#78350f">adaleti ve güzel ahlakı hakkındaki gözlemleri</text>\n  <text x="35" y="160" font-size="10.5" font-weight="bold" fill="#78350f">• Nefîse bint Müneyye aracılığıyla evlilik teklifi</text>\n  <text x="35" y="184" font-size="10.5" font-weight="bold" fill="#78350f">• Ebu Talip ve Amr bin Esed\'in katılımıyla nikâh</text>\n  <text x="35" y="210" font-size="11" font-weight="bold" fill="#b91c1c">• Hz. Peygamber 25, Hz. Hatice 40 yaşındaydı.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">25 YILLIK MUTLU YUVA VE ÇOCUKLARI</text>\n  <text x="378" y="96" font-size="11" font-weight="bold" fill="#581c87">• Erkek Çocukları (Küçük yaşta vefat ettiler):</text>\n  <text x="390" y="116" font-size="11" font-weight="bold" fill="#6b21a8">1. Kâsım (Ebu\'l-Kâsım künyesinin kaynağı)</text>\n  <text x="390" y="136" font-size="11" font-weight="bold" fill="#6b21a8">2. Abdullah (Tayyib / Tâhir)</text>\n  <text x="378" y="162" font-size="11" font-weight="bold" fill="#581c87">• Kız Çocukları:</text>\n  <text x="390" y="182" font-size="11" font-weight="bold" fill="#6b21a8">1. Zeyneb · 2. Rukiyye · 3. Ümmü Gülsüm</text>\n  <text x="390" y="202" font-size="11" font-weight="bold" fill="#15803d">4. Fâtıma (Hz. Peygamber\'in soyunu sürdüren kızı)</text>\n  <text x="378" y="224" font-size="10" fill="#581c87">(Not: İbrahim, Mısırlı Hz. Mâriye\'den dünyaya gelmiştir.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İLK VAHİY SÜRECİNDE HZ. HATİCE\'NİN DESTEĞİ VE HÜZÜN YILI (619)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">HİRA\'DAN DÖNÜŞ VE TESELLİ SÖZLERİ (610)</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#1e3a8a">• «Allah\'a yemin ederim ki Allah seni hiçbir zaman</text>\n  <text x="35" y="110" font-size="10.5" font-weight="bold" fill="#1e3a8a">  utandırmaz ve yalnız bırakmaz! Çünkü sen:»</text>\n  <text x="45" y="132" font-size="10.5" fill="#1d4ed8">1. Akrabanı gözetirsin (sıla-i rahim),</text>\n  <text x="45" y="150" font-size="10.5" fill="#1d4ed8">2. Doğru konuşur, emaneti korursun,</text>\n  <text x="45" y="168" font-size="10.5" fill="#1d4ed8">3. İşini göremeyenlerin yükünü taşırsın,</text>\n  <text x="45" y="186" font-size="10.5" fill="#1d4ed8">4. Yoksula verir, misafiri ağırlarsın,</text>\n  <text x="45" y="204" font-size="10.5" fill="#1d4ed8">5. Hak yolunda felakete uğrayanlara yardım edersin.</text>\n  <text x="35" y="224" font-size="10.5" font-weight="bold" fill="#b91c1c">• Bilge akrabası Varaka bin Nevfel\'e götürmesi</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">İLK MÜSLÜMAN VE HÜZÜN YILI (SENETÜ\'L-HÜZN)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#15803d">• Yeryüzünde İslam\'ı kabul eden İLK İNSAN /</text>\n  <text x="385" y="114" font-size="11" font-weight="bold" fill="#15803d">İLK MÜSLÜMAN olma şerefi (610).</text>\n  <text x="375" y="140" font-size="10.5" font-weight="bold" fill="#7f1d1d">• 3 yıllık boykotta (616-619) Şi\'b-i Ebî Tâlib</text>\n  <text x="385" y="156" font-size="10.5" fill="#991b1b">محallesinde tüm servetini İslam için harcaması.</text>\n  <text x="375" y="182" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Vefatı (M. 619 — Bi\'setin 10. yılı):</text>\n  <text x="385" y="198" font-size="10.5" fill="#991b1b">Ebu Talip ile art arda vefatı → HÜZÜN YILI.</text>\n  <text x="375" y="222" font-size="10.5" font-weight="bold" fill="#0f172a">• Cebrail (a.s.) aracılığıyla Allah\'ın selamı ve Cennet köşkü!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
